<script lang="ts">import Avatar from'@fex-design/svelte/primitive/avatar';import AvatarFallback from'@fex-design/svelte/primitive/avatar-fallback';import AvatarImage from'@fex-design/svelte/primitive/avatar-image';import{Bubble,BubbleAction,BubbleActions,BubbleContent,BubbleReaction,BubbleReactions}from'@fex-design/svelte/primitive/bubble';import{Message,MessageAvatar,MessageBody,MessageContent}from'@fex-design/svelte/primitive/message';import Button from'@fex-design/svelte/ui/button';import Card from'@fex-design/svelte/ui/card';let liked=$state(false)</script>{#snippet copy({props}:{props:Record<string,unknown>})}<Button class={String(props.class??'')} variant="ghost" size="xs">Copy</Button>{/snippet}<Card title="Action and reaction positions" description="side controls the top or bottom edge; align controls the logical start or end position."><div class="mx-auto grid w-full max-w-2xl gap-8 py-8"><Message><MessageAvatar><Avatar><AvatarImage src="/avatar-demo.svg" alt="Oliver"/><AvatarFallback>O</AvatarFallback></Avatar></MessageAvatar><MessageBody><MessageContent><Bubble><BubbleContent>Tests passed on the first try. All 142 of them.</BubbleContent><BubbleActions side="top" align="end"><BubbleAction>Pin</BubbleAction><BubbleAction render={copy}/></BubbleActions><BubbleReactions side="bottom" align="start"><BubbleReaction aria-label="Helpful" pressed={liked} onchange={v=>liked=v}>🎉</BubbleReaction><BubbleReaction aria-label="Celebrate" count={2}>👏</BubbleReaction></BubbleReactions></Bubble></MessageContent></MessageBody></Message><Message side="end"><MessageBody><MessageContent><Bubble variant="solid"><BubbleContent>Are you sure I can run this command?</BubbleContent><BubbleReactions side="top" align="end"><BubbleReaction aria-label="Watching">👀</BubbleReaction></BubbleReactions><BubbleActions side="bottom" align="end"><BubbleAction>Yes, run it</BubbleAction><BubbleAction>Cancel</BubbleAction></BubbleActions></Bubble></MessageContent></MessageBody></Message><p class="text-center text-xs text-muted-foreground">Every part accepts class, so callers can replace the preset edge placement.</p></div></Card>
